import "./TopSeries.css";

const TopSeries = () => {
  const names = [
    { name: "Anna", count: 75234 },
    { name: "Eva", count: 68921 },
    { name: "Maria", count: 67210 },
    { name: "Lena", count: 65100 },
    { name: "Karin", count: 62345 },
    { name: "Emma", count: 60120 },
    { name: "Sara", count: 58930 },
    { name: "Kristina", count: 57500 },
    { name: "Margareta", count: 55910 },
    { name: "Elin", count: 54800 },
  ];

  return (
    <div className="top-series">
      {names.map((item, idx) => (
        <div
          key={idx}
          className={`rank rank-${idx + 1}`}
          style={{
            width:
              idx === 0
                ? "100%"
                : idx === 1
                ? "85%"
                : idx === 2 
                ? "70%"
				: idx === 7
                ? "50%"
                : idx === 8
                ? "40%"
                : idx === 9
                ? "35%"
                : "60%",
          }}
        >
          {idx + 1}. {item.name} ({item.count})
        </div>
      ))}
    </div>
  );
};

export default TopSeries;
